-- Fakt kartochkalarining ruscha matni — 14-partiya:
-- Munis Xorazmiy, Ogahiy, Muhammad Rahimxon Feruz.

-- ===== Munis Xorazmiy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Мунис Хорезми?', fact_ru = 'Я родился в 1778 году в селении Кыят близ Хивы. Мой отец — Амир Авазбий.' WHERE id = 409;
UPDATE fact_cards SET topic_ru = 'Моя служба при дворе', question_ru = 'В какой должности служил Мунис Хорезми при дворе?', fact_ru = 'В 1800 году, после смерти отца, я был назначен ко двору писцом указов.' WHERE id = 410;
UPDATE fact_cards SET topic_ru = 'Мой первый диван', question_ru = 'Когда Мунис Хорезми составил свой первый поэтический диван?', fact_ru = 'Свой первый поэтический диван я составил в 1804 году.' WHERE id = 411;
UPDATE fact_cards SET topic_ru = '«Саводи таълим»', question_ru = 'Как называется трактат Муниса Хорезми об обучении грамоте?', fact_ru = 'В 1804 году я написал стихотворный трактат «Саводи таълим» о каллиграфии и обучении грамоте.' WHERE id = 412;
UPDATE fact_cards SET topic_ru = '«Фирдавс ул-икбол»', question_ru = 'По чьему поручению Мунис Хорезми написал «Фирдавс ул-икбол»?', fact_ru = 'В 1806 году по поручению Эльтузархана я начал писать труд «Фирдавс ул-икбол» по истории Хивинского ханства.' WHERE id = 413;
UPDATE fact_cards SET topic_ru = 'Мой большой диван', question_ru = 'Сколько стихотворных строк собрано в диване «Мунис ул-ушшок»?', fact_ru = 'Я скончался в 1829 году. В свой диван «Мунис ул-ушшок» я собрал более двадцати тысяч стихотворных строк — после моей смерти, в 1880 году, он был напечатан в Хиве.' WHERE id = 414;
UPDATE fact_cards SET topic_ru = 'Мой перевод', question_ru = 'Чей труд Мунис Хорезми перевёл на тюркский язык?', fact_ru = 'В 1819 году я начал переводить на тюркский язык труд Мирхонда «Равзат ус-сафо» и завершил первый том.' WHERE id = 415;
UPDATE fact_cards SET topic_ru = 'Мой продолжатель', question_ru = 'Кто завершил незаконченные труды Муниса Хорезми?', fact_ru = 'Мои незаконченные труды — летопись и перевод — завершил мой ученик и племянник Агахи.' WHERE id = 416;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Мунис Хорезми?', fact_ru = 'Я скончался в 1829 году.' WHERE id = 417;
UPDATE fact_cards SET topic_ru = 'Значение моего псевдонима', question_ru = 'Что означает псевдоним Муниса Хорезми?', fact_ru = 'Моё настоящее имя — Шермухаммад. «Мунис» — мой псевдоним, он означает «близкий друг, наперсник». Под этим именем я и писал свои стихи.' WHERE id = 1723;
UPDATE fact_cards SET topic_ru = 'Моя должность мираба', question_ru = 'В какой должности, связанной с распределением воды, служил Мунис Хорезми?', fact_ru = 'В Хорезме без воды земледелия не бывает, потому мираб, распределявший воду, был весьма почётной должностью. Я исполнял и обязанности мираба. После моей смерти эта должность перешла к моему племяннику Агахи.' WHERE id = 1724;
UPDATE fact_cards SET topic_ru = 'Моё каллиграфическое мастерство', question_ru = 'Каким искусством в совершенстве владел Мунис Хорезми?', fact_ru = 'Я в совершенстве владел искусством каллиграфии. Переписывать рукописные книги красивым почерком было для меня и ремеслом, и отрадой.' WHERE id = 1725;
UPDATE fact_cards SET topic_ru = 'Моё образование', question_ru = 'Где учился Мунис Хорезми?', fact_ru = 'В юности я учился в хивинских медресе. Изучив арабский и персидский языки, я читал произведения восточных поэтов в подлиннике.' WHERE id = 1726;
UPDATE fact_cards SET topic_ru = 'Язык моего творчества', question_ru = 'На каком языке писал свои стихи Мунис Хорезми?', fact_ru = 'Хотя я хорошо знал персидский, стихи свои писал главным образом на родном тюркском, то есть староузбекском языке. И диваны мои составлены на этом же языке.' WHERE id = 1727;
UPDATE fact_cards SET topic_ru = 'Мой наставник Навои', question_ru = 'Какого великого поэта Мунис Хорезми считал своим наставником?', fact_ru = 'Своим наставником я считал Алишера Навои. Я с любовью читал его газели и писал стихи, следуя за ним.' WHERE id = 1728;
UPDATE fact_cards SET topic_ru = 'Мои рукописи сегодня', question_ru = 'Где сегодня хранятся рукописи произведений Муниса Хорезми?', fact_ru = 'Рукописные списки моих произведений дошли до наших дней. Их бережно хранят в собрании Института востоковедения имени Абу Райхана Беруни в Ташкенте.' WHERE id = 1729;

-- ===== Ogahiy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Агахи?', fact_ru = 'Я родился 17 декабря 1809 года в селении Кыят близ Хивы, в семье мирабов. Моё полное имя — Мухаммадриза, сын Эрниязбека.' WHERE id = 418;
UPDATE fact_cards SET topic_ru = 'Моя учёба', question_ru = 'Какие языки изучил Агахи?', fact_ru = 'Учась в хивинских медресе, я изучил арабский, персидский и турецкий языки; особенно любил читать поэзию Навои.' WHERE id = 419;
UPDATE fact_cards SET topic_ru = 'Должность мираба', question_ru = 'Вместо кого Агахи был назначен мирабом?', fact_ru = 'В 1829 году, после смерти моего дяди Муниса, Аллакулихан назначил меня мирабом вместо него — я ведал делами распределения воды.' WHERE id = 420;
UPDATE fact_cards SET topic_ru = 'Моё увечье', question_ru = 'По какой причине Агахи ушёл в отставку с должности мираба?', fact_ru = 'В 1845 году я упал с коня и повредил ногу; в 1857 году я ушёл в отставку с должности мираба.' WHERE id = 421;
UPDATE fact_cards SET topic_ru = 'Мои исторические труды', question_ru = 'Какие исторические труды написал Агахи?', fact_ru = 'Я написал труды «Риёз уд-давла» (1844), «Зубдат ут-таворих» (1845–1846), «Джоме ул-вокеоти султоний» (1857), «Гулшани давлат» (1865) и «Шохиди икбол» (1872).' WHERE id = 422;
UPDATE fact_cards SET topic_ru = 'О чём я писал', question_ru = 'Историю каких народов изложил Агахи в своих трудах?', fact_ru = 'В своих трудах я изложил историю и культурную жизнь узбеков, туркмен, каракалпаков и казахов Хорезма.' WHERE id = 423;
UPDATE fact_cards SET topic_ru = 'Как я продолжил дело дяди', question_ru = 'Какие труды своего дяди Муниса завершил Агахи?', fact_ru = 'Я завершил летопись моего дяди Муниса «Фирдавс ул-икбол» и его перевод «Равзат ус-сафо».' WHERE id = 424;
UPDATE fact_cards SET topic_ru = 'Память обо мне', question_ru = 'Что устроено в Кыяте в память об Агахи?', fact_ru = 'В Кыяте устроены мой дом-музей и сад, перед музеем поставлен мой памятник; моим именем названы улицы и школы.' WHERE id = 425;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Агахи?', fact_ru = 'Я скончался 14 декабря 1874 года.' WHERE id = 426;
UPDATE fact_cards SET topic_ru = 'Мой диван', question_ru = 'Как Агахи назвал свой диван стихов?', fact_ru = 'Свои стихи я собрал в диван под названием «Таъвиз ул-ошикин», то есть «Оберег влюблённых».' WHERE id = 1751;
UPDATE fact_cards SET topic_ru = 'Мои переводы', question_ru = 'Какие знаменитые произведения перевёл Агахи с персидского на узбекский?', fact_ru = 'Я перевёл с персидского на узбекский язык около двадцати произведений. Среди них «Гулистан» Саади и «Кабуснаме» Кайкавуса.' WHERE id = 1752;
UPDATE fact_cards SET topic_ru = 'Значение моего псевдонима', question_ru = 'Что означает псевдоним Агахи?', fact_ru = 'Мой псевдоним «Агахи» происходит от слова «огох» и означает «сведущий, проницательный человек».' WHERE id = 1753;
UPDATE fact_cards SET topic_ru = 'Мои стихи на двух языках', question_ru = 'На каких языках писал стихи Агахи?', fact_ru = 'В моём диване наряду с узбекскими стихами есть и стихи, написанные на персидском языке. Я свободно творил на обоих языках.' WHERE id = 1754;
UPDATE fact_cards SET topic_ru = 'Мой ученик Феруз', question_ru = 'Какой хивинский хан считал Агахи своим наставником?', fact_ru = 'Хивинский хан Мухаммад Рахимхан Второй считал меня своим наставником. Это был хан-поэт, писавший стихи под псевдонимом «Феруз».' WHERE id = 1755;
UPDATE fact_cards SET topic_ru = 'Мои газели в песнях', question_ru = 'Как исполняются газели Агахи в наши дни?', fact_ru = 'На мои газели сложены напевы: хафизы поют их на лады хорезмского макома.' WHERE id = 1756;
UPDATE fact_cards SET topic_ru = 'Тема справедливости', question_ru = 'Какие мысли проводил Агахи в своих стихах?', fact_ru = 'В своих стихах я возвеличивал справедливость и совестливость и сострадал горю простого трудового люда.' WHERE id = 1757;

-- ===== Muhammad Rahimxon Feruz =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Мухаммад Рахимхан Феруз?', fact_ru = 'Я родился в 1845 году в Хиве.' WHERE id = 435;
UPDATE fact_cards SET topic_ru = 'Восшествие на престол', question_ru = 'Когда Мухаммад Рахимхан Феруз сел на хивинский престол?', fact_ru = 'После смерти моего отца Саида Мухаммадхана я сел на хивинский престол в 1864 году.' WHERE id = 436;
UPDATE fact_cards SET topic_ru = 'Мой псевдоним', question_ru = 'Под каким псевдонимом Мухаммад Рахимхан писал свои стихи?', fact_ru = 'Свои стихи я писал под псевдонимом «Феруз».' WHERE id = 437;
UPDATE fact_cards SET topic_ru = 'Мой диван', question_ru = 'Когда был составлен сборник «Девони Феруз»?', fact_ru = 'В 1879 году был составлен мой сборник «Девони Феруз».' WHERE id = 438;
UPDATE fact_cards SET topic_ru = 'Мой наставник', question_ru = 'Кто был наставником Феруза?', fact_ru = 'Моим наставником был поэт и историк Агахи; при моём дворе творили такие поэты, как Комил и Табибий.' WHERE id = 439;
UPDATE fact_cards SET topic_ru = 'Моя литография', question_ru = 'Какие книги печатались в литографии, открытой Ферузом в Хиве?', fact_ru = 'В Хиве по моему велению была открыта литография — в ней печатались произведения Навои и сборник хорезмских поэтов «Маджмуат уш-шуаро».' WHERE id = 440;
UPDATE fact_cards SET topic_ru = 'Моё покровительство музыке', question_ru = 'Что поддерживал Феруз в области музыки?', fact_ru = 'При моём дворе был создан музыкальный ансамбль; я поддерживал работы, связанные с напевами «Наво», «Дугох» и «Сегох» в традиции Шашмакома.' WHERE id = 441;
UPDATE fact_cards SET topic_ru = 'Моё медресе', question_ru = 'Когда Феруз возвёл медресе, названное его именем?', fact_ru = 'В 1871 году я возвёл двухэтажное медресе, названное моим именем; под моим покровительством было воздвигнуто более тридцати сооружений.' WHERE id = 442;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Мухаммад Рахимхан Феруз?', fact_ru = 'Я скончался в 1910 году.' WHERE id = 443;
UPDATE fact_cards SET topic_ru = 'Моё полное имя', question_ru = 'Под каким ещё именем известен в истории Мухаммад Рахимхан Феруз?', fact_ru = 'Моё полное имя — Мухаммад Рахим Бахадурхан. В истории я известен также под именем Мухаммад Рахимхан Сони, то есть Мухаммад Рахимхан Второй.' WHERE id = 1578;
UPDATE fact_cards SET topic_ru = 'Моя династия', question_ru = 'К какой династии принадлежал Мухаммад Рахимхан Феруз?', fact_ru = 'Я происхожу из династии кунгратов, правившей Хивинским ханством. Мои деды тоже сидели на хивинском престоле.' WHERE id = 1579;
UPDATE fact_cards SET topic_ru = 'Гандемианский договор', question_ru = 'Какой договор подписал Мухаммад Рахимхан Феруз в 1873 году?', fact_ru = 'В 1873 году я был вынужден подписать Гандемианский договор с Российской империей. После этого ханство утратило свою самостоятельность и стало зависимым от России.' WHERE id = 1580;
UPDATE fact_cards SET topic_ru = 'Поэты моего двора', question_ru = 'Какие поэты творили при дворе Мухаммада Рахимхана Феруза?', fact_ru = 'При своём дворе я собрал многих поэтов своего времени. В мою пору творили такие мастера, как Комил Хорезми, Баяни, Табибий и Аваз Утар.' WHERE id = 1581;
UPDATE fact_cards SET topic_ru = 'Тазкира поэтов', question_ru = 'Какая тазкира была составлена по поручению Мухаммада Рахимхана Феруза?', fact_ru = 'Поручив это дело поэту Табибию, я велел составить тазкиру «Маджмуат уш-шуаро», собравшую стихи хорезмских поэтов.' WHERE id = 1582;
UPDATE fact_cards SET topic_ru = 'Дело перевода', question_ru = 'Какое дело особенно развилось в Хиве во времена Мухаммада Рахимхана Феруза?', fact_ru = 'В мою пору в Хиве развилось переводческое дело: по моему повелению множество книг с персидского и арабского языков было переведено на узбекский.' WHERE id = 1583;
UPDATE fact_cards SET topic_ru = 'Мой наследник', question_ru = 'Кто сел на хивинский престол после Мухаммада Рахимхана Феруза?', fact_ru = 'После меня на хивинский престол сел мой сын Исфандиярхан.' WHERE id = 1584;
